{
  "name": "opencode-stats-for-nerds",
  "version": "1.0.0",
  "description": "OpenCode TUI plugin — token usage, speed, and cost stats in the sidebar",
  "author": "imluckii",
  "license": "MIT",
  "type": "module",
  "main": "./tui.tsx",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/imluckii/opencode-stats-for-nerds.git"
  },
  "homepage": "https://github.com/imluckii/opencode-stats-for-nerds#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "stats",
    "tokens",
    "tui",
    "sidebar"
  ],
  "exports": {
    ".": { "import": "./tui.tsx" },
    "./tui": { "import": "./tui.tsx" }
  },
  "files": [
    "tui.tsx",
    "README.md",
    "LICENSE"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "latest",
    "solid-js": "^1.9.10"
  }
}
